com.mirth.connect.plugins.javascriptstep.script:
var HttpClients =
    Packages.org.apache.http.impl.client.HttpClients;

var HttpGet =
    Packages.org.apache.http.client.methods.HttpGet;

var EntityUtils =
    Packages.org.apache.http.util.EntityUtils;

var jwksUrl =
    'http://mirth-lab-keycloak:8080' +
    '/realms/mirth-lab/protocol/openid-connect/certs';

var client = null;
var response = null;

try {

    client =
        HttpClients.createDefault();

    var request =
        new HttpGet(jwksUrl);

    request.addHeader(
        'Accept',
        'application/json'
    );

    response =
        client.execute(request);

    var statusCode =
        response
            .getStatusLine()
            .getStatusCode();

    var responseBody =
        EntityUtils.toString(
            response.getEntity(),
            'UTF-8'
        );

    if (statusCode !== 200) {
        throw new Error(
            'JWKS endpoint returned HTTP ' +
            statusCode
        );
    }

    var jwks =
        JSON.parse(responseBody);

    var keyCount =
        jwks.keys != null
            ? jwks.keys.length
            : 0;

    channelMap.put(
        'jwksReachable',
        keyCount > 0
    );

    channelMap.put(
        'jwksKeyCount',
        keyCount
    );

    logger.info(
        '[CH06 JWT] jwksReachable=' +
        (keyCount > 0) +
        ', jwksKeyCount=' +
        keyCount
    );

} finally {

    if (response != null) {
        response.close();
    }

    if (client != null) {
        client.close();
    }
}

var authorizationValueSourceMap = sourceMap.get('headers').getHeaderList('authorization');
var authorizationHeader = null;
var bearerToken = null;

if (authorizationValueSourceMap != null) {
    var authorizationValues = authorizationValueSourceMap;

    if (authorizationValues != null &&
        !authorizationValues.isEmpty()) {

        authorizationHeader =
            String(authorizationValues.get(0));
    }
}

if (authorizationHeader != null &&
    authorizationHeader.indexOf('Bearer ') === 0) {

    bearerToken =
        authorizationHeader.substring(7).trim();
}

channelMap.put(
    'authorizationHeaderPresent',
    authorizationHeader != null
);

channelMap.put(
    'bearerTokenPresent',
    bearerToken != null &&
    bearerToken.length > 0
);

var authenticationAccepted =
    bearerToken != null &&
    bearerToken.length > 0;

channelMap.put(
    'authenticationAccepted',
    authenticationAccepted
);

logger.info(
    '[CH06 AUTH] authorizationHeaderPresent=' +
    (authorizationHeader != null) +
    ', bearerTokenPresent=' +
    (bearerToken != null && bearerToken.length > 0)
);

com.mirth.connect.plugins.javascriptrule.script:
function loadKeycloakJwks() {

    var HttpClients =
        Packages.org.apache.http.impl.client.HttpClients;

    var HttpGet =
        Packages.org.apache.http.client.methods.HttpGet;

    var EntityUtils =
        Packages.org.apache.http.util.EntityUtils;

    var jwksUrl =
        'http://mirth-lab-keycloak:8080' +
        '/realms/mirth-lab/protocol/openid-connect/certs';

    var client = null;
    var response = null;

    try {

        client =
            HttpClients.createDefault();

        var request =
            new HttpGet(jwksUrl);

        request.addHeader(
            'Accept',
            'application/json'
        );

        response =
            client.execute(request);

        var statusCode =
            response
                .getStatusLine()
                .getStatusCode();

        if (statusCode !== 200) {
            throw new Error(
                'JWKS endpoint returned HTTP ' +
                statusCode
            );
        }

        var responseBody =
            EntityUtils.toString(
                response.getEntity(),
                'UTF-8'
            );

        return JSON.parse(
            String(responseBody)
        );

    } finally {

        if (response != null) {
            response.close();
        }

        if (client != null) {
            client.close();
        }
    }
}

function decodeBase64UrlBytes(value) {

    var normalized =
        String(value)
            .replace(/-/g, '+')
            .replace(/_/g, '/');

    while (normalized.length % 4 !== 0) {
        normalized += '=';
    }

    return Packages.java.util.Base64
        .getDecoder()
        .decode(normalized);
}

function decodeBase64Url(value) {

    var normalized =
        String(value)
            .replace(/-/g, '+')
            .replace(/_/g, '/');

    while (normalized.length % 4 !== 0) {
        normalized += '=';
    }

    var bytes =
        Packages.java.util.Base64
            .getDecoder()
            .decode(normalized);

    return String(
        new Packages.java.lang.String(
            bytes,
            Packages.java.nio.charset.StandardCharsets.UTF_8
        )
    );
}

var headers = sourceMap.get('headers');

if (headers == null) {
    channelMap.put('httpStatusCode', '401');
    channelMap.put('httpAuthResult', 'missing_authorization_header');
    channelMap.put(
	    'httpResponseBody',
	    JSON.stringify({
	        status: 'rejected',
	        reason: 'missing_authorization_header'
	    })
	);
    return false;
}

var authorizationValues =
    headers.getHeaderList('authorization');

if (authorizationValues == null ||
    authorizationValues.isEmpty()) {

    channelMap.put('httpStatusCode', '401');
    channelMap.put('httpAuthResult', 'missing_authorization_header');
    channelMap.put(
	    'httpResponseBody',
	    JSON.stringify({
	        status: 'rejected',
	        reason: 'missing_authorization_header'
	    })
	);
    return false;
}

var authorizationHeader =
    String(authorizationValues.get(0));

if (authorizationHeader.indexOf('Bearer ') !== 0) {

    channelMap.put('httpStatusCode', '401');
    channelMap.put('httpAuthResult', 'unsupported_authentication_scheme');
    channelMap.put(
	    'httpResponseBody',
	    JSON.stringify({
	        status: 'rejected',
	        reason: 'unsupported_authentication_scheme'
	    })
	);

    return false;
}

var bearerToken =
    authorizationHeader.substring(7).trim();

if (bearerToken.length === 0) {

    channelMap.put('httpStatusCode', '401');
    channelMap.put('httpAuthResult', 'missing_bearer_token');
    channelMap.put(
	    'httpResponseBody',
	    JSON.stringify({
	        status: 'rejected',
	        reason: 'missing_bearer_token'
	    })
	);

    return false;
}

var jwtParts = bearerToken.split('.');

if (jwtParts.length !== 3) {
    channelMap.put('httpStatusCode', '401');
    channelMap.put(
        'httpAuthResult',
        'invalid_jwt_structure'
    );
    channelMap.put(
        'httpResponseBody',
        JSON.stringify({
            status: 'rejected',
            reason: 'invalid_jwt_structure'
        })
    );

    return false;
}

var jwtHeaderText;
var jwtPayloadText;

try {

    jwtHeaderText =
        decodeBase64Url(jwtParts[0]);

    jwtPayloadText =
        decodeBase64Url(jwtParts[1]);

} catch (e) {

    channelMap.put('httpStatusCode', '401');
    channelMap.put(
        'httpAuthResult',
        'jwt_decode_failed'
    );
    channelMap.put(
        'httpResponseBody',
        JSON.stringify({
            status: 'rejected',
            reason: 'jwt_decode_failed'
        })
    );

    return false;
}

var jwtHeader;
var jwtClaims;

try {

    jwtHeader = JSON.parse(jwtHeaderText);
    jwtClaims = JSON.parse(jwtPayloadText);

} catch (e) {

    channelMap.put('httpStatusCode', '401');
    channelMap.put(
        'httpAuthResult',
        'invalid_jwt_json'
    );
    channelMap.put(
        'httpResponseBody',
        JSON.stringify({
            status: 'rejected',
            reason: 'invalid_jwt_json'
        })
    );

    return false;
}

// Now we have access to the JSON object.

if (String(jwtHeader.alg) !== 'RS256') {

    channelMap.put('httpStatusCode', '401');
    channelMap.put(
        'httpAuthResult',
        'unsupported_jwt_algorithm'
    );
    channelMap.put(
        'httpResponseBody',
        JSON.stringify({
            status: 'rejected',
            reason: 'unsupported_jwt_algorithm'
        })
    );

    return false;
}

var jwks;

try {

    jwks =
        loadKeycloakJwks();

} catch (e) {

    channelMap.put(
        'httpStatusCode',
        '503'
    );

    channelMap.put(
        'httpAuthResult',
        'jwks_unavailable'
    );

    channelMap.put(
        'httpResponseBody',
        JSON.stringify({
            status: 'error',
            reason: 'authentication_service_unavailable'
        })
    );

    return false;
}

var signingJwk = null;

if (jwks.keys != null) {

    for (var i = 0; i < jwks.keys.length; i++) {

        var candidate =
            jwks.keys[i];

        if (
            String(candidate.kid) ===
                String(jwtHeader.kid) &&

            String(candidate.kty) === 'RSA' &&

            String(candidate.use) === 'sig' &&

            String(candidate.alg) === 'RS256'
        ) {

            signingJwk =
                candidate;

            break;
        }
    }
}

if (signingJwk == null) {

    channelMap.put(
        'httpStatusCode',
        '401'
    );

    channelMap.put(
        'httpAuthResult',
        'signing_key_not_found'
    );

    channelMap.put(
        'httpResponseBody',
        JSON.stringify({
            status: 'rejected',
            reason: 'signing_key_not_found'
        })
    );

    return false;
}

var modulusBytes =
    decodeBase64UrlBytes(
        signingJwk.n
    );

var exponentBytes =
    decodeBase64UrlBytes(
        signingJwk.e
    );

var modulus =
    new java.math.BigInteger(
        1,
        modulusBytes
    );

var exponent =
    new java.math.BigInteger(
        1,
        exponentBytes
    );

var publicKeySpec =
    new java.security.spec.RSAPublicKeySpec(
        modulus,
        exponent
    );

var keyFactory =
    java.security.KeyFactory
        .getInstance('RSA');

var publicKey =
    keyFactory.generatePublic(
        publicKeySpec
    );

// Construct exactly the bytes signed:
var signingInput =
    jwtParts[0] +
    '.' +
    jwtParts[1];

var signatureBytes =
    decodeBase64UrlBytes(
        jwtParts[2]
    );

var verifier =
    java.security.Signature
        .getInstance(
            'SHA256withRSA'
        );

verifier.initVerify(
    publicKey
);

verifier.update(
    new java.lang.String(
        signingInput
    ).getBytes(
        java.nio.charset.StandardCharsets.US_ASCII
    )
);

var signatureValid =
    verifier.verify(
        signatureBytes
    );

// Reject invalid signature

if (!signatureValid) {

    channelMap.put(
        'httpStatusCode',
        '401'
    );

    channelMap.put(
        'httpAuthResult',
        'invalid_jwt_signature'
    );

    channelMap.put(
        'httpResponseBody',
        JSON.stringify({
            status: 'rejected',
            reason: 'invalid_jwt_signature'
        })
    );

    return false;
}

var expectedIssuer =
    'http://localhost:8080/realms/mirth-lab';

if (String(jwtClaims.iss) !== expectedIssuer) {

    channelMap.put('httpStatusCode', '401');
    channelMap.put(
        'httpAuthResult',
        'invalid_issuer'
    );
    channelMap.put(
        'httpResponseBody',
        JSON.stringify({
            status: 'rejected',
            reason: 'invalid_issuer'
        })
    );

    return false;
}

var nowEpochSeconds =
    Math.floor(
        java.lang.System.currentTimeMillis() / 1000
    );

if (jwtClaims.exp == null ||
    Number(jwtClaims.exp) <= nowEpochSeconds) {

    channelMap.put('httpStatusCode', '401');
    channelMap.put(
        'httpAuthResult',
        'token_expired'
    );
    channelMap.put(
        'httpResponseBody',
        JSON.stringify({
            status: 'rejected',
            reason: 'token_expired'
        })
    );

    return false;
}

var expectedAudience =
    'mirth-radiology-api';

var audienceValid = false;

if (jwtClaims.aud instanceof Array) {

    for (var a = 0; a < jwtClaims.aud.length; a++) {

        if (String(jwtClaims.aud[a]) === expectedAudience) {
            audienceValid = true;
            break;
        }
    }

} else if (jwtClaims.aud != null) {

    audienceValid =
        String(jwtClaims.aud) === expectedAudience;
}

if (!audienceValid) {

    channelMap.put('httpStatusCode', '401');
    channelMap.put(
        'httpAuthResult',
        'invalid_audience'
    );
    channelMap.put(
        'httpResponseBody',
        JSON.stringify({
            status: 'rejected',
            reason: 'invalid_audience'
        })
    );

    return false;
}

var expectedClient =
    'radiology-order-client';

if (String(jwtClaims.azp) !== expectedClient) {

    channelMap.put('httpStatusCode', '401');
    channelMap.put(
        'httpAuthResult',
        'invalid_authorized_party'
    );
    channelMap.put(
        'httpResponseBody',
        JSON.stringify({
            status: 'rejected',
            reason: 'invalid_authorized_party'
        })
    );

    return false;
}

var requiredRole =
    'radiology-order.submit';

var roleValid = false;

if (
    jwtClaims.realm_access != null &&
    jwtClaims.realm_access.roles != null
) {

    var roles =
        jwtClaims.realm_access.roles;

    for (var r = 0; r < roles.length; r++) {

        if (String(roles[r]) === requiredRole) {
            roleValid = true;
            break;
        }
    }
}

if (!roleValid) {

    channelMap.put('httpStatusCode', '403');
    channelMap.put(
        'httpAuthResult',
        'missing_required_role'
    );
    channelMap.put(
        'httpResponseBody',
        JSON.stringify({
            status: 'rejected',
            reason: 'missing_required_role'
        })
    );

    return false;
}

channelMap.put(
    'httpStatusCode',
    '200'
);

channelMap.put(
    'httpAuthResult',
    'authenticated_and_authorized'
);

channelMap.put(
    'authenticatedClient',
    String(jwtClaims.azp)
);

channelMap.put(
    'jwtSignatureValid',
    true
);

channelMap.put(
    'jwtAudienceValid',
    true
);

channelMap.put(
    'jwtRoleValid',
    true
);

channelMap.put(
    'httpResponseBody',
    JSON.stringify({
        status: 'accepted',
        reason: 'authenticated_and_authorized'
    })
);

return true;

channel.postprocessingScript:
var responseBody = channelMap.get('httpResponseBody');

if (responseBody == null) {
    responseBody = JSON.stringify({
        status: 'error',
        reason: 'response_not_generated'
    });
}

return ResponseFactory.getSentResponse(
    String(responseBody)
);

channel.deployScript:
// This script executes once when the channel is deployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;

channel.undeployScript:
// This script executes once when the channel is undeployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;
